cat > /app/core.py <<'PY'
import sqlite3,hashlib,secrets,datetime,json,base64,re,os,zoneinfo
DB='/app/data/huddle.db'
def connect():
 c=sqlite3.connect(DB,timeout=10,isolation_level=None); c.row_factory=sqlite3.Row;c.execute('PRAGMA busy_timeout=10000');return c
class tx:
 def __enter__(self): self.c=connect();self.c.execute('BEGIN IMMEDIATE');return self.c
 def __exit__(self,t,v,b):
  self.c.execute('ROLLBACK' if t else 'COMMIT');self.c.close()
def now_iso(): return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def init_db():
 c=connect();c.execute('PRAGMA journal_mode=WAL')
 c.executescript('''CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT,avatar_url TEXT,status_text TEXT,status_emoji TEXT);
 CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT);
 CREATE TABLE IF NOT EXISTS members(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
 CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0,last_event_id INTEGER DEFAULT 0);
 CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
 CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0);
 CREATE TABLE IF NOT EXISTS events(channel_id INTEGER,event_id INTEGER,payload TEXT,PRIMARY KEY(channel_id,event_id));
 CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,PRIMARY KEY(message_id,user_id,emoji));
 CREATE TABLE IF NOT EXISTS dms(user_a INTEGER,user_b INTEGER,channel_id INTEGER,PRIMARY KEY(user_a,user_b));
 CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,uploader_id INTEGER,filename TEXT,content_type TEXT,size INTEGER,created_at TEXT,message_id INTEGER);
 CREATE TABLE IF NOT EXISTS groupsx(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER,UNIQUE(workspace_id,handle));
 CREATE TABLE IF NOT EXISTS group_members(group_id INTEGER,user_id INTEGER,PRIMARY KEY(group_id,user_id));
 CREATE TABLE IF NOT EXISTS presence(conn_id TEXT PRIMARY KEY,user_id INTEGER,last_seen REAL)''');c.close()
def hash_password(p): return hashlib.sha256(p.encode()).hexdigest()
def verify_password(p,s): return hash_password(p)==s
def issue_token(c,uid):
 t=secrets.token_urlsafe(24);c.execute('INSERT INTO tokens VALUES(?,?)',(t,uid));return t
def user_for_token(t):
 if not t:return None
 c=connect();r=c.execute('SELECT u.* FROM users u JOIN tokens t ON u.id=t.user_id WHERE t.token=?',(t,)).fetchone();c.close();return r
def user_to_json(r): return {k:r[k] for k in ['id','username','display_name','timezone','avatar_url','status_text','status_emoji']}
def workspace_to_json(r): return dict(r)
def channel_json(r): return dict(r)
def emit(c,ch,typ,payload):
 n=c.execute('UPDATE channels SET last_event_id=last_event_id+1 WHERE id=? RETURNING last_event_id',(ch,)).fetchone()[0]
 x={'type':typ,'event_id':n,'channel_id':ch,**payload};c.execute('INSERT INTO events VALUES(?,?,?)',(ch,n,json.dumps(x)));return x
def msg_json(c,r):
 d=dict(r);d['author']=user_to_json(c.execute('SELECT * FROM users WHERE id=?',(r['author_id'],)).fetchone());d['parent_id']=r['parent_id'];d['reply_count']=c.execute('SELECT count(*) FROM messages WHERE parent_id=? AND deleted=0',(r['id'],)).fetchone()[0];d['edited_at']=r['edited_at'];d['reactions']=reactions(c,r['id']);d['mentions']=mention_ids(c,r['body'],r['channel_id'],r['author_id']);d['files']=[];return d
def reactions(c,mid):
 out=[]
 for e in c.execute('SELECT DISTINCT emoji FROM reactions WHERE message_id=? ORDER BY rowid',(mid,)):
  ids=[x[0] for x in c.execute('SELECT user_id FROM reactions WHERE message_id=? AND emoji=? ORDER BY rowid',(mid,e[0]))];out.append({'emoji':e[0],'count':len(ids),'user_ids':ids})
 return out
def mention_ids(c,body,ch,author):
 ids=set(); cr=c.execute('SELECT workspace_id FROM channels WHERE id=?',(ch,)).fetchone()[0]
 for u in re.findall(r'(?<!\w)@([A-Za-z0-9_]+)',body):
  if u=='channel':
   ids.update(x[0] for x in c.execute('SELECT user_id FROM channel_members WHERE channel_id=?',(ch,)))
  elif u=='here': ids.update(x[0] for x in c.execute('SELECT user_id FROM channel_members WHERE channel_id=?',(ch,)))
  else:
   x=c.execute('SELECT id FROM users WHERE username=? AND id IN (SELECT user_id FROM members WHERE workspace_id=?)',(u,cr)).fetchone()
   if x: ids.add(x[0])
 ids.discard(author);return sorted(ids)
if __name__=='__main__':
 import sys
 if '--init-db' in sys.argv:init_db()
PY
cat > /app/server.py <<'PY'
import asyncio,json,os,re,sys,uuid,base64
from aiohttp import web,WSMsgType
import core
core.init_db(); NODE=int(sys.argv[sys.argv.index('--node')+1]) if '--node' in sys.argv else 0
WSS=set()
def js(x,status=200): return web.json_response(x,status=status)
def err(s,m): return js({'error':m},s)
async def body(r):
 try:return await r.json()
 except:return None
def user(r):
 h=r.headers.get('Authorization','');return core.user_for_token(h[7:] if h.startswith('Bearer ') else '')
def auth(r):
 u=user(r);return u
def member(c,ch,uid):
 x=c.execute('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(ch,uid)).fetchone();return bool(x)
async def api(r):
 u=auth(r)
 if not u:return err(401,'unauthorized')
 p=r.path.split('/')
 c=core.connect(); method=r.method
 try:
  if p[2]=='users' and p[3]=='me' and method=='PATCH':
   b=await body(r) or {}; allowed={'display_name':(1,80),'status_text':(0,140),'status_emoji':(0,32),'avatar_url':(0,512),'timezone':None}
   for k,v in b.items():
    if k not in allowed or not isinstance(v,str) or (allowed[k] and not allowed[k][0]<=len(v)<=allowed[k][1]) or (k=='timezone' and not __import__('zoneinfo').zoneinfo.ZoneInfo(v)): return err(400,'invalid')
   with core.tx() as z:
    z.execute('UPDATE users SET '+','.join(k+'=?' for k in b)+' WHERE id=?',(*b.values(),u['id']))
   return js({'user':core.user_to_json(core.user_for_token(r.headers['Authorization'][7:]))})
  if p[2]=='users' and method=='GET':
   x=c.execute('SELECT * FROM users WHERE id=?',(p[3],)).fetchone();return js({'user':core.user_to_json(x)}) if x else err(404,'not found')
  if p[2]=='auth' and p[3]=='me':return js({'user':core.user_to_json(u)})
  if p[2]=='auth' and p[3] in ('register','login'):
   b=await body(r) or {}; un=b.get('username');pw=b.get('password')
   if p[3]=='register':
    if not isinstance(un,str) or not re.fullmatch(r'[A-Za-z0-9_]+',un) or not isinstance(pw,str) or len(pw)<8:return err(400,'invalid')
    try:
     with core.tx() as z:z.execute('INSERT INTO users(username,password,display_name,timezone,avatar_url,status_text,status_emoji) VALUES(?,?,?,?,?,?,?)',(un,core.hash_password(pw),b.get('display_name') or un,'UTC','','','')); uid=z.lastrowid;tok=core.issue_token(z,uid)
    except: return err(409,'duplicate')
    return js({'user':core.user_to_json(core.user_for_token(tok)),'token':tok},201)
   x=c.execute('SELECT * FROM users WHERE username=?',(un,)).fetchone()
   if not x or not core.verify_password(pw or '',x['password']):return err(401,'wrong password')
   with core.tx() as z:tok=core.issue_token(z,x['id'])
   return js({'user':core.user_to_json(x),'token':tok})
  if p[2]=='health':return js({'status':'ok','node_id':NODE})
  return err(404,'not found')
 finally:c.close()
async def main():
 app=web.Application();app.router.add_route('*','/api/{tail:.*}',api);app.router.add_get('/',lambda r: web.Response(text='<html><body><h1>Huddle</h1></body></html>',content_type='text/html'));web.run_app(app,host='127.0.0.1',port=8000+NODE)
if __name__=='__main__':asyncio.run(main())
PY
mkdir -p /app/static
cat > /app/static/index.html <<'EOF'
<!doctype html><html><body><h1>Huddle</h1></body></html>
EOF
/app/start.sh >/tmp/huddle.log 2>&1 & echo $! > /tmp/huddle.pid
sleep 3
curl -s http://127.0.0.1:8000/api/health
```

